{"implementation": "def solve(case):
    from collections import deque

    nodes = case["nodes"]
    required_symbols = set(case["required_symbols"])

    node_map = {n["id"]: n for n in nodes}

    children = {n["id"]: [] for n in nodes}
    for n in nodes:
        if n["parent"] is not None:
            children[n["parent"]].append(n["id"])

    removed = set()

    roots = [n["id"] for n in nodes if n["parent"] is None]
    queue = deque(roots)

    while queue:
        node_id = queue.popleft()
        node = node_map[node_id]
        parent_id = node["parent"]

        if parent_id in removed:
            removed.add(node_id)
        elif node["removable"] and node["symbol"] not in required_symbols:
            removed.add(node_id)

        for child_id in children[node_id]:
            queue.append(child_id)

    all_ids = [n["id"] for n in nodes]
    removed_list = [nid for nid in all_ids if nid in removed]
    retained_list = [nid for nid in all_ids if nid not in removed]

    return {
        "removed_node_ids": removed_list,
        "retained_node_ids": retained_list
    }
"}
